package com.tenora365.controller;import com.tenora365.service.NotificationService;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/notifications") public class NotificationController{final NotificationService n;@Value("${SMS_WEBHOOK_URL:}")String sms;@Value("${WHATSAPP_WEBHOOK_URL:}")String wa;NotificationController(NotificationService x){n=x;}@PostMapping("/email")Object email(@RequestBody Map<String,String>x){return Map.of("status",n.email(x.get("to"),x.get("subject"),x.get("body")));}@PostMapping("/sms")Object sms(@RequestBody Map<String,String>x){return Map.of("status",n.webhook(sms,x));}@PostMapping("/whatsapp")Object whatsapp(@RequestBody Map<String,String>x){return Map.of("status",n.webhook(wa,x));}}
